<?php
namespace Ishep\Services;use PDO;use Throwable;use DomainException;use Ishep\Repositories\{FinanceRepository,AuditLogRepository,MembershipApplicationRepository,RoleRepository};use Ishep\Support\{Money,PublicReference};
final class FinanceService
{
 public function __construct(private PDO $db,private FinanceRepository $finance,private AuditLogRepository $audits,private RoleRepository $roles){}
 private function tx(callable $fn):mixed{$owned=!$this->db->inTransaction();if($owned)$this->db->beginTransaction();try{$r=$fn();if($owned)$this->db->commit();return$r;}catch(Throwable $e){if($owned&&$this->db->inTransaction())$this->db->rollBack();throw$e;}}
 public function assertStaff(int $uid):void{if(!array_intersect($this->roles->roles($uid),['finance','super_user']))throw new DomainException('Finance or super-user authorization is required.');}
 private function date(string $v,string $label):string{$d=\DateTimeImmutable::createFromFormat('!Y-m-d',$v);if(!$d||$d->format('Y-m-d')!==$v)throw new DomainException($label.' must be a valid date.');return$v;}
 public function createFee(int $actor,array $in,string $ip):string{$this->assertStaff($actor);$type=(int)($in['membership_type_id']??0);$amount=Money::normalize((string)($in['amount']??''));$currency=Money::currency((string)($in['currency']??'ZAR'));$period=(string)($in['billing_period']??'annual');if(!in_array($period,['once','monthly','annual'],true))throw new DomainException('Select a valid billing period.');$from=$this->date((string)($in['effective_from']??''),'Effective from');$to=trim((string)($in['effective_to']??''));$to=$to===''?null:$this->date($to,'Effective to');if($to&&$to<$from)throw new DomainException('Effective to cannot precede effective from.');if($this->finance->overlappingFee($type,$from,$to))throw new DomainException('An active fee schedule overlaps this period.');$ref=PublicReference::make('FEE');return$this->tx(function()use($actor,$type,$amount,$currency,$period,$from,$to,$ref,$ip){$id=$this->finance->createFee([$ref,$type,$amount,$currency,$period,$from,$to,$actor]);$this->finance->event('fee_schedule',$ref,$actor,null,'active','fee_schedule.created');$this->audits->record($actor,'finance.fee_created','membership_fee_schedule',$id,$ip);return$ref;});}
 public function deactivateFee(int $actor,string $ref,string $ip):void{$this->assertStaff($actor);$fee=$this->finance->feeByReference($ref);if(!$fee)throw new DomainException('Fee schedule not found.');if(!(int)$fee['active'])throw new DomainException('Fee schedule is already inactive.');$this->tx(function()use($actor,$fee,$ref,$ip){$this->finance->deactivateFee((int)$fee['id']);$this->finance->event('fee_schedule',$ref,$actor,'active','inactive','fee_schedule.deactivated');$this->audits->record($actor,'finance.fee_deactivated','membership_fee_schedule',(int)$fee['id'],$ip);});}
 public function provisionApproved(array $app,int $actor,string $ip):array{return$this->tx(function()use($app,$actor,$ip){$existing=$this->finance->membershipByApplication((int)$app['id']);if($existing)return$existing;$fee=$this->finance->effectiveFee((int)$app['membership_type_id']);$positive=$fee&&Money::minor((string)$fee['amount'])>0;$status=$positive?'pending_payment':'awaiting_fee_configuration';$number=PublicReference::make('MEM');$mid=$this->finance->createMembership([$number,(int)$app['user_id'],(int)$app['id'],(int)$app['membership_type_id'],$status]);$this->finance->event('membership',$number,$actor,null,$status,'membership.created');if($positive){$inv=PublicReference::make('INV');$description=$app['membership_type_name'].' membership fee ('.$fee['billing_period'].')';$iid=$this->finance->createInvoice([$inv,(int)$app['user_id'],$mid,(int)$app['id'],$fee['currency'],$fee['amount'],$fee['amount'],$fee['amount']],$description,(string)$fee['amount']);$this->finance->event('invoice',$inv,$actor,null,'issued','invoice.issued');$this->audits->record($actor,'finance.invoice_issued','invoice',$iid,$ip);}$this->audits->record($actor,'finance.membership_created','membership',$mid,$ip);return$this->finance->membershipByApplication((int)$app['id']);});}
 public function recordPayment(int $actor,array $in,string $ip):string{$this->assertStaff($actor);$invoice=$this->finance->invoice((string)($in['invoice_number']??''));if(!$invoice)throw new DomainException('Invoice not found.');$amount=Money::normalize((string)($in['amount']??''));if(Money::minor($amount)<=0)throw new DomainException('Payment amount must be positive.');if(Money::currency((string)($in['currency']??''))!==$invoice['currency'])throw new DomainException('Payment currency must match the invoice.');if(Money::minor($amount)>Money::minor((string)$invoice['balance_due']))throw new DomainException('Overpayments are not accepted; the amount exceeds the invoice balance.');$method=(string)($in['payment_method']??'');if(!in_array($method,['eft','cash','card_manual','other_manual'],true))throw new DomainException('Select a supported manual payment method.');$manual=trim((string)($in['manual_reference']??''));if(strlen($manual)<3||strlen($manual)>100)throw new DomainException('Enter a valid manual payment reference.');$received=trim((string)($in['received_at']??''));if(!$received)$received=gmdate('Y-m-d H:i:s');else{$d=\DateTimeImmutable::createFromFormat('Y-m-d\TH:i',$received,new \DateTimeZone('UTC'));if(!$d)throw new DomainException('Enter a valid received date.');$received=$d->format('Y-m-d H:i:s');}$note=trim((string)($in['note']??''));if(strlen($note)>1000)throw new DomainException('Payment note is too long.');$key=hash('sha256',$invoice['id'].'|'.strtoupper($manual).'|'.$amount);$ref=PublicReference::make('PAY');return$this->tx(function()use($actor,$invoice,$amount,$method,$manual,$received,$note,$key,$ref,$ip){$locked=$this->finance->invoiceById((int)$invoice['id']);if(!$locked||Money::minor($amount)>Money::minor((string)$locked['balance_due']))throw new DomainException('The invoice balance changed; review the payment again.');try{$pid=$this->finance->createPayment([$ref,(int)$invoice['user_id'],$amount,$invoice['currency'],$method,$manual,$received,$actor,$note?:null,$key]);}catch(\PDOException $e){if($e->getCode()==='23000')throw new DomainException('This manual payment reference or submission was already recorded.');throw$e;}$this->finance->allocate($pid,(int)$invoice['id'],$amount);$calc=$this->finance->recalculateInvoice((int)$invoice['id']);$this->finance->event('payment',$ref,$actor,null,'completed','payment.recorded');$this->finance->event('invoice',$invoice['invoice_number'],$actor,$invoice['status'],$calc['status'],'invoice.payment_allocated');if($calc['status']==='paid'){$this->finance->setMembershipStatus((int)$invoice['membership_id'],'active');$this->finance->event('membership',$invoice['membership_number'],$actor,'pending_payment','active','membership.activated');}$this->audits->record($actor,'finance.payment_recorded','payment',$pid,$ip);return$ref;});}
 public function reversePayment(int $actor,string $ref,string $reason,string $ip):string{$this->assertStaff($actor);$reason=trim($reason);if(strlen($reason)<10)throw new DomainException('Provide a meaningful reversal reason.');$payment=$this->finance->payment($ref);if(!$payment)throw new DomainException('Payment not found.');if($payment['status']!=='completed'||$payment['reversed_by_reference'])throw new DomainException('This payment cannot be reversed again.');$allocation=$this->finance->allocationForPayment((int)$payment['id']);if(!$allocation)throw new DomainException('Payment allocation not found.');$newRef=PublicReference::make('PAY');return$this->tx(function()use($actor,$payment,$allocation,$reason,$newRef,$ip){$rid=$this->finance->createReversal([$newRef,(int)$payment['user_id'],$payment['amount'],$payment['currency'],'reversal','REV-'.$payment['payment_reference'],$actor,'Reversal entry',(int)$payment['id'],$reason,hash('sha256','reverse|'.$payment['id'])]);$this->finance->markReversed((int)$payment['id']);$calc=$this->finance->recalculateInvoice((int)$allocation['invoice_id']);if($calc['status']!=='paid')$this->finance->setMembershipStatus((int)$allocation['membership_id'],'pending_payment');$this->finance->event('payment',$payment['payment_reference'],$actor,'completed','reversed','payment.reversed',$reason);$this->audits->record($actor,'finance.payment_reversed','payment',$rid,$ip);return$newRef;});}
 public function requestRefund(int $uid,string $paymentRef,string $amount,string $reason,string $ip):string{$payment=$this->finance->payment($paymentRef,$uid);if(!$payment||$payment['status']!=='completed')throw new DomainException('Eligible payment not found.');$amount=Money::normalize($amount);$reason=trim($reason);if(Money::minor($amount)<=0||Money::minor($amount)>Money::minor($this->finance->refundable((int)$payment['id'])))throw new DomainException('Refund amount exceeds the currently refundable balance.');if(strlen($reason)<10||strlen($reason)>1000)throw new DomainException('Provide a meaningful refund reason.');$ref=PublicReference::make('RFR');return$this->tx(function()use($uid,$payment,$amount,$reason,$ref,$ip){$this->finance->createRefundRequest([$ref,(int)$payment['id'],$uid,$amount,$reason]);$this->finance->event('refund_request',$ref,$uid,null,'requested','refund.requested');$this->audits->record($uid,'finance.refund_requested','refund_request',null,$ip);return$ref;});}
 public function decideRefund(int $actor,string $ref,string $action,string $reason,string $ip):void{$this->assertStaff($actor);$request=$this->finance->refundRequest($ref);if(!$request||$request['status']!=='requested')throw new DomainException('Refund request is not awaiting a decision.');if(!in_array($action,['approve','reject'],true))throw new DomainException('Invalid refund decision.');if($action==='reject'&&strlen(trim($reason))<5)throw new DomainException('A rejection reason is required.');$to=$action==='approve'?'approved':'rejected';$this->tx(function()use($actor,$request,$ref,$to,$reason,$ip){$this->finance->decideRefund((int)$request['id'],$to,$actor,trim($reason));$this->finance->event('refund_request',$ref,$actor,'requested',$to,'refund.'.$to,trim($reason)?:null);$this->audits->record($actor,'finance.refund_'.$to,'refund_request',(int)$request['id'],$ip);});}
 public function processRefund(int $actor,string $ref,string $method,string $manual,string $ip):string{$this->assertStaff($actor);$request=$this->finance->refundRequest($ref);if(!$request||$request['status']!=='approved')throw new DomainException('Only an approved refund can be processed.');if(!in_array($method,['eft','cash','card_manual','other_manual'],true)||strlen(trim($manual))<3)throw new DomainException('Enter valid manual refund details.');$refundRef=PublicReference::make('REF');return$this->tx(function()use($actor,$request,$ref,$method,$manual,$refundRef,$ip){try{$this->finance->createRefund([$refundRef,(int)$request['id'],(int)$request['payment_id'],$request['requested_amount'],$method,$actor,trim($manual)]);}catch(\PDOException $e){if($e->getCode()==='23000')throw new DomainException('This refund was already processed or its reference is duplicated.');throw$e;}$this->finance->decideRefund((int)$request['id'],'processed',$actor,(string)$request['decision_reason']);$allocation=$this->finance->allocationForPayment((int)$request['payment_id']);if($allocation){$calc=$this->finance->recalculateInvoice((int)$allocation['invoice_id']);if($calc['status']!=='paid')$this->finance->setMembershipStatus((int)$allocation['membership_id'],'pending_payment');}$this->finance->event('refund_request',$ref,$actor,'approved','processed','refund.processed','Manually recorded refund '.$refundRef);$this->audits->record($actor,'finance.refund_processed','refund_request',(int)$request['id'],$ip);return$refundRef;});}
}
